'use strict';
(() => {
 const E=KK_ENGINE,D=KK_DATA,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const KEY='kod-kasifleri-demo-v1';let storageOK=true,state=E.seed();
 try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.version===1&&saved.results&&Array.isArray(saved.assignments)&&Array.isArray(saved.observations)&&Array.isArray(saved.events))state={...state,...saved};}catch{storageOK=false}
 if(!D.profiles.some(p=>p.id===state.profile))state.profile='k01';if(!['4-5','6-8','9-12'].includes(state.age))state.age='6-8';if(!['mint','orange','blue'].includes(state.color))state.color='mint';
 const params=new URLSearchParams(window.KK_PREVIEW_CONFIG?.search||location.search);let role=Object.keys(D.roles).includes(params.get('role'))?params.get('role'):'child';let task=D.themes.find(t=>t.id===(params.get('task')||params.get('story')))?.id||'T01';if(['4-5','6-8','9-12'].includes(params.get('age')))state.age=params.get('age');
 let commands=[],loopCount=3,order=[],sequence=[],hintLevel=0,runVersion=0,running=false,toastTimer,verifyIndex=0,verifyCorrect=0,labels={},classificationTested=false,currentProject={},dragIndex=null;
 const hints={
  route:['Hedefin, başlangıcın hangi tarafında olduğuna bak.','Turuncu yıldız hedef; koyu hücreler engel. Önce boş bir çizgiyi izlemeyi düşün.','Parkurun en sol sütunu ve en üst satırı açık.','Önce bir köşeye, ardından hedefe giden iki ayrı yol düşün.','Bir kâğıda üç kare çiz. Bir arkadaşınla sağ ve yukarı komutlarını sırayla dene.'],
  loop:['Hangi iki hareket aynı sırayla tekrar ediyor?','Her tekrar robotu bir kare sağa, bir kare yukarı taşır.','Hedef üç kare sağda ve üç kare yukarıda.','Bir tekrarın sonucunu düşün; aynı hareketi kaç kez yapmalısın?','İki hareketten oluşan bir dans seç ve birkaç kez tekrarla.'],
  debug:['Önce hazır komutları çalıştır ve durduğu adımı gözlemle.','Başlangıcın hemen sağında bir engel var.','İlk komut için sağ ve yukarı seçeneklerini karşılaştır.','Yolunu önce sol kenardan üst köşeye, sonra hedefe böl.','Yerde yön kartlarıyla engelin etrafından dolaşan bir yol kur.'],
  sequence:['Bir adımı yapmadan önce hangi bilgiye veya malzemeye ihtiyacın var?','Fidenin suya ihtiyacı olup olmadığını önce kontrol et.','Suyu hazırlamak, sulamaktan önce gelir.','Önce kontrol ve hazırlık; sonra uygulama ve gözlem.','Günlük bir işini bir yetişkinle üç ayrı harekete böl.'],
  water:['Kuru toprak ile nemli toprağa aynı karar verilmeli mi?','25 düşük, 70 daha yüksek bir nem değeridir.','Eşiğin 25 ile 70 arasında bir değer olmasını düşün.','Önce kuru örneği, sonra nemli örneği ayrı ayrı dene.','Bir saksının toprağını bir yetişkinle gözlemle. Bu örnek gerçek sulama tavsiyesi değildir.'],
  sensor:['Uzaklığı mı, ışığı mı, sesi mi ölçmek istiyoruz?','Görevde karar verilen değer santimetre ile gösteriliyor.','Mesafe sensörü yakınlık hakkında bilgi verir.','Önce sensörü seç; sonra 10 cm ve 80 cm örneklerini karşılaştır.','Bir nesneye yaklaşırken aradaki uzaklığın değişmesini gözlemle.'],
  event:['Işığın yanması için hangi olay bekleniyor?','Senaryoda özellikle düğmeye basılmasından söz ediliyor.','Giriş düğme, çıkış ışık olabilir.','Önce olayı seç, sonra olaya bağlı tepkiyi seç.','El çırpınca arkadaşının el kaldırdığı bir oyun kur.'],
  motor:['İki tekerlek eşit hızla dönerse ne olur?','Hızlar farklı olursa robot bir yana yönelir.','Bu yük için 1–3 arası hızlar kontrollü kabul ediliyor.','Önce hızları eşitle, sonra ikisini birlikte düşük bir değere getir.','İki elinle bir nesneyi eşit biçimde ilerletmeyi dene.'],
  classify:['Grupları hangi özelliğe göre ayırıyoruz?','Yuvarlaklar A, üçgenler B grubuna ait. Renk bu görevde önemli değil.','Aynı şeklin farklı renklerini karşılaştır.','Önce şekle karar ver; sonra renk değişse de aynı grupta tut.','Kâğıt şekilleri renkten bağımsız iki gruba ayır.'],
  verify:['Bir iddiayı kontrol etmek için hangi kanıt gerekli?','Emin bir cümle tek başına kanıt sayılmaz.','Özel bilgilerini bir uygulamayla paylaşmadan önce yetişkinine danış.','İddia, kanıt ve güvenli seçim basamaklarını ayrı ayrı düşün.','Bir yetişkinle doğru sandığınız basit bir bilgiyi güvenilir bir kaynaktan kontrol edin.'],
  project:['Önce çözmek istediğin ihtiyacı seç.','Çözümün doğrudan o ihtiyacı azaltmalı.','Su sorunu, nem sensörü ve su tüketimi ölçümüyle eşleşebilir.','İhtiyaç, çözüm ve ölçütü üç kart gibi yan yana düşün.','Okulda iyileştirmek istediğin bir şeyi öğretmeninle konuş.'],
  final:['Takımda herkesin görevi belirli mi?','Çalıştığını anlamak için bir test gerekir.','Beklenmeyen sonuçta yeniden denemek öğrenmenin parçasıdır.','Rol, test ve iyileştirme adımlarını sırayla kur.','Küçük bir kâğıt köprü tasarla, test et ve nasıl güçlendireceğini düşün.']
 };
 const verifyQuestions=[
  {q:'Robot rehber “Bu bitki hiç su istemez” diyor. Ne yaparsın?',options:['Söylediğini kesin doğru kabul ederim.','Bitkinin bakım bilgisini güvenilir bir kaynak ve yetişkinle kontrol ederim.','Bütün bitkilere aynı kuralı uygularım.'],correct:1,feedback:'Güzel: İddia, uygun kaynak ve gözlemle doğrulanmalı.'},
  {q:'Bir uygulama ev adresini ve fotoğrafını istiyor. Güvenli seçim hangisi?',options:['Hemen gönderirim.','Arkadaşımın bilgilerini yazarım.','Paylaşmadan durur, güvendiğim bir yetişkine danışırım.'],correct:2,feedback:'Özel bilgilerini korumak ve yetişkin desteği almak güvenli bir seçimdir.'},
  {q:'Model yalnız kırmızı daire örnekleri gördü. Mavi bir daireyi yanlış tanıdı. Ne önerirsin?',options:['Farklı renklerde daire örnekleri ekleyip yeniden test etmek.','Mavi olan her şeye üçgen demek.','Modelin hata yapamayacağını söylemek.'],correct:0,feedback:'Çeşitli örnekler ve yeni örneklerle test etmek, hatayı anlamamıza yardımcı olur.'}
 ];
 function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false}updateSidebar()}
 function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4000)}
 function showDialog(title,html,label='KOD KAŞİFLERİ DEMOSU'){$('#app-dialog-eyebrow').textContent=label;$('#app-dialog-body').innerHTML=`<h2 id="app-dialog-title">${title}</h2>${html}`;if(!$('#app-dialog').open)$('#app-dialog').showModal()}
 function closeDialog(){$('#app-dialog').close()}
 function theme(){return D.themes.find(t=>t.id===task)}
 function result(id=task,profile=state.profile){return state.results[profile+':'+id]||{attempts:0,hints:0,complete:false,physical:false}}
 function record(type){E.record(state,state.profile,task,{type});save();if($('[data-attempt-count]'))$('[data-attempt-count]').textContent=result().attempts+' deneme';if($('[data-task-completion]'))$('[data-task-completion]').textContent=result().complete?'✓ Dijital görev tamamlandı':'Keşfetmeye hazır'}
 function setRole(next){role=next;runVersion++;running=false;render();}
 function setTask(id){if(!D.themes.some(t=>t.id===id))return;task=id;role='child';resetExercise();render();if(innerWidth<980)$('#workspace').scrollIntoView({behavior:'smooth',block:'start'})}
 function resetExercise(){runVersion++;running=false;hintLevel=0;loopCount=3;verifyIndex=0;verifyCorrect=0;labels={};classificationTested=false;currentProject={};
  commands=task==='T04'?['R','U','U','R']:[];
  sequence=state.age==='4-5'?['Toprağı kontrol et','Birlikte sula','Sonucu gözle']:['Toprağı kontrol et','Suyu hazırla','Uygun miktarda sula','Sonucu gözle'];order=sequence.map((_,i)=>i).reverse();
 }
 function updateSidebar(){
  $('#profile-select').value=state.profile;$('#age-select').value=state.age;$('#profile-avatar').textContent=D.profiles.find(p=>p.id===state.profile).initial;
  const s=E.stats(state,state.profile);$('#portfolio-count').textContent=s.completed;
  document.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===state.color)));
  document.documentElement.style.setProperty('--robot-color',({mint:'#34cbaa',orange:'#f2a751',blue:'#6ba9f5'})[state.color]);
  $('#mission-list').innerHTML=D.themes.map(t=>`<button data-task="${t.id}" ${t.id===task?'aria-current="step"':''}><span>${t.id.slice(1)}</span><span>${t.title}</span>${result(t.id).complete?'<b aria-label="Dijital görev tamamlandı">✓</b>':''}</button>`).join('');
 }
 function render(){
  runVersion++;running=false;document.querySelectorAll('[data-role]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.role===role)));
  document.body.dataset.role=role;$('#sidebar').hidden=role==='institution';updateSidebar();
  const u=new URL(location.href);u.searchParams.set('role',role);u.searchParams.set('task',task);u.searchParams.set('age',state.age);u.searchParams.delete('story');try{history.replaceState(null,'',u)}catch{}
  if(role==='child')renderChild();else if(role==='teacher')renderTeacher();else if(role==='parent')renderParent();else renderInstitution();
 }
 function childHeading(){const t=theme(),r=result();return `<div class="workspace-top"><div><span class="eyebrow">${t.id} / ${t.title.toLocaleUpperCase('tr')}</span><h1>${t.story}</h1><p>${t.intro}</p></div><button class="quiet-button" data-action="story">Hikâyeyi oku ▷</button></div><div class="task-meta"><span>${state.age.replace('-','–')} yaş ${state.age==='4-5'?'· Yetişkin eşliğiyle':''}</span><span data-attempt-count>${r.attempts} deneme</span><span data-task-completion>${r.complete?'✓ Dijital görev tamamlandı':'Keşfetmeye hazır'}</span>${state.assignments.some(a=>a.profile===state.profile&&a.task===task)?'<span>Öğretmeninin atadığı görev</span>':''}</div>`}
 function renderChild(){const t=theme();$('#workspace').innerHTML=childHeading()+`<div class="task-layout"><section class="exercise-card" aria-label="Etkileşimli görev">${exercise(t)}</section><aside class="guide-panel"><span class="guide-icon" aria-hidden="true">✦</span><h2>Robot rehberin</h2><p id="hint-text">${t.question}</p><button class="hint-button" data-action="hint">Bir ipucu al <span>✦</span></button><span class="hint-note">Hazır kurallarla çalışan örnek rehber</span><div class="learning-target"><h3>Bugünkü becerim</h3><p>${t.skill}</p></div><div class="task-feedback" id="task-feedback" role="status" aria-live="polite">${result().complete?'Bu görevi daha önce tamamladın. Yeni bir çözüm deneyebilirsin.':'Hazır olduğunda denemeye başla.'}</div></aside></div><section id="transfer" class="transfer-panel" ${result().complete?'':'hidden'}></section>`;renderTransfer();bindExercise();}
 function exercise(t){
  if(['route','debug','loop'].includes(t.type)){const b=E.board(task,state.age);return `<div class="exercise-heading"><h2>${t.type==='loop'?'Tekrar eden yolu kur':'Komutlarını kur'}</h2><span>${b.size} × ${b.size} parkur</span></div><div class="board-legend"><span>◆ Robot</span><span>✦ Hedef</span>${b.obstacles.length?'<span>■ Engel</span>':''}</div><div class="game-board" id="game-board" style="--grid-size:${b.size}" role="img" aria-label="Robot başlangıçta sol altta. Hedef ${t.type==='loop'?'üç kare sağda ve üç kare yukarıda':'sağ üstte'}. Koyu hücreler engel.">${boardHTML(b)}</div>${t.type==='loop'?`<div class="loop-editor"><span>Tekrar et</span><label for="loop-count" class="sr-only">Tekrar sayısı</label><input type="number" id="loop-count" min="1" max="6" value="${loopCount}"><div><b>→ Sağa</b><b>↑ Yukarı</b></div></div>`:`<div class="command-palette" aria-label="Komut ekle">${Object.entries(D.arrows).map(([id,arrow])=>`<button data-cmd="${id}" aria-label="${D.directions[id]} komutu ekle"><b>${arrow}</b><span>${D.directions[id]}</span></button>`).join('')}</div><div class="command-title"><strong>Komut dizim</strong><span id="command-count">${commands.length} / 24</span></div><div class="command-list" id="command-list" aria-label="Komutlar"></div><p class="micro">Bir komuta dokunarak çıkar. Sırayı değiştirmek için taşıma düğmelerini kullan.</p>`}<div class="exercise-actions"><button class="button navy" data-action="run">Çalıştır <span>▷</span></button><button class="quiet-button" data-action="clear">${t.type==='loop'?'Tekrar sayısını sıfırla':'Komutları temizle'}</button></div><p class="micro">Robot hareketi bu parkurda canlandırılır; fiziksel robot bağlı değildir.</p>`}
  if(t.type==='sequence')return `<div class="exercise-heading"><h2>Adımları sırala</h2><span>Yukarı / aşağı taşı</span></div><div id="sequence-list" class="sequence-list"></div><button class="button navy" data-action="check-sequence">Sıramı kontrol et ✓</button>`;
  if(t.type==='event')return `<div class="exercise-heading"><h2>Bir olay, bir tepki</h2><span>Giriş → Çıkış</span></div><div class="event-preview"><span id="event-light">☼</span><p id="event-message">Düzenek, seçtiğin olayı bekliyor.</p></div><div class="form-grid"><label>Ne olduğunda?<select id="event-trigger"><option value="">Olay seç</option><option value="button">Düğmeye basılınca</option><option value="sound">Ses duyulunca</option><option value="time">Zaman dolunca</option></select></label><label>Ne olsun?<select id="event-output"><option value="">Tepki seç</option><option value="light">Işık yansın</option><option value="motor">Motor dönsün</option><option value="bell">Zil çalsın</option></select></label></div><button class="button navy" data-action="check-event">Düğmeye bas ve dene ▷</button>`;
  if(t.type==='sensor')return `<div class="exercise-heading"><h2>Robot neyi algılamalı?</h2><span>Mesafe senaryosu</span></div><label class="control-label">Sensör seç<select id="sensor-kind"><option value="">Sensör seç</option><option value="light">Işık sensörü</option><option value="distance">Mesafe sensörü</option><option value="sound">Ses sensörü</option></select></label><label class="control-label">Durma eşiği: <output id="distance-out">30</output> cm<input id="distance-threshold" type="range" min="5" max="90" step="5" value="30"></label><p class="rule-line">Mesafe eşikten küçükse <strong>DUR</strong>, değilse <strong>İLERLE</strong>.</p><div class="sensor-cases"><article><strong>10 cm</strong><span>Yakın engel</span><b id="near-status">—</b></article><article><strong>80 cm</strong><span>Açık yol</span><b id="far-status">—</b></article></div><button class="button navy" data-action="check-sensor">İki durumu test et ▷</button><p class="micro">Değerler eğitim senaryosudur; gerçek robot güvenlik eşiği değildir.</p>`;
  if(t.type==='motor')return `<div class="exercise-heading"><h2>İki tekerleği dengele</h2><span>Hız 1–5</span></div><div class="motor-preview"><div id="motor-marker">◆</div><div class="motor-track"></div></div><div class="form-grid"><label>Sol motor: <output id="left-out">2</output><input id="left-motor" type="range" min="1" max="5" value="2"></label><label>Sağ motor: <output id="right-out">4</output><input id="right-motor" type="range" min="1" max="5" value="4"></label></div><p class="rule-line">Hedef: Düz ilerleme ve <strong>1–3 arası kontrollü hız</strong>.</p><button class="button navy" data-action="check-motor">Hareketi dene ▷</button><p class="micro">Basitleştirilmiş hareket canlandırmasıdır; fiziksel motor bağlı değildir.</p>`;
  if(t.type==='water')return `<div class="exercise-heading"><h2>Seranın sulama kuralı</h2><span>Örnek sensör verisi</span></div><div class="water-head"><span>SU / TOPRAK</span><strong>Ölç. Karşılaştır. Karar ver.</strong></div><label class="control-label">Nem eşiği: <output id="water-out">45</output>%<input id="water-threshold" type="range" min="0" max="100" step="5" value="45"></label><p class="rule-line">Nem eşikten düşükse <strong>SULA</strong>, değilse <strong>DUR</strong>.</p><div class="sensor-cases"><article><strong>%25</strong><span>Kuru toprak örneği</span><b id="dry-status">—</b></article><article><strong>%70</strong><span>Nemli toprak örneği</span><b id="wet-status">—</b></article></div><button class="button navy" data-action="check-water">Sulama kuralını test et ▷</button><p class="micro">Değerler öğrenme için kurgulanmıştır; gerçek sulama önerisi değildir.</p>`;
  if(t.type==='classify')return `<div class="exercise-heading"><h2>Örneklerle sınıflandır</h2><span>4 öğretme örneği</span></div><p class="rule-line"><strong>A grubu: Daireler · B grubu: Üçgenler.</strong><br>Farklı renkler, aynı şeklin grubunu değiştirmesin.</p><div class="classification-grid">${[{s:'●',c:'teal'},{s:'▲',c:'red'},{s:'●',c:'red'},{s:'▲',c:'teal'}].map((x,i)=>`<div class="sample"><span class="shape ${x.c}" aria-label="${x.c==='teal'?'Turkuaz':'Kırmızı'} ${x.s==='●'?'daire':'üçgen'}">${x.s}</span><div><button data-label="A" data-example="${i}" aria-pressed="false">A</button><button data-label="B" data-example="${i}" aria-pressed="false">B</button></div></div>`).join('')}</div><button class="button navy" data-action="train">Örnekleri kontrol et ✓</button><div id="test-sample" class="test-sample" hidden><h3>Yeni örnek: Mavi daire</h3><span class="shape blue">●</span><p>Öğrenilen kurala göre hangi gruba ait?</p><button data-test-label="A" class="quiet-button">A grubu</button><button data-test-label="B" class="quiet-button">B grubu</button></div><p class="micro">Bu, örnek ve genelleme ilişkisini gösteren kural tabanlı canlandırmadır; gerçek model eğitimi yapılmaz.</p>`;
  if(t.type==='verify')return `<div class="exercise-heading"><h2>İddia ve kanıt</h2><span id="verify-progress">1 / 3 soru</span></div><div id="verify-area"></div>`;
  if(t.type==='project')return `<div class="exercise-heading"><h2>Bir çözüm planı kur</h2><span>İhtiyaç → Çözüm → Ölçüt</span></div><div class="project-fields"><label>Okulda hangi ihtiyacı ele alıyoruz?<select id="project-problem"><option value="">İhtiyaç seç</option><option value="water">Gereksiz su kullanımı</option><option value="energy">Boş sınıfta yanan ışıklar</option><option value="access">Atölye araçlarının yerini bulma güçlüğü</option></select></label><label>Uygun çözüm hangisi?<select id="project-solution"><option value="">Çözüm seç</option><option value="water">Nem sensörüne bağlı sulama</option><option value="energy">Işık ve varlık bilgisine göre aydınlatma</option><option value="access">Simgeli, kolay erişilen malzeme düzeni</option></select></label><label>Sonucu nasıl gözlemleyebiliriz?<select id="project-measure"><option value="">Ölçüt seç</option><option value="water">Kullanılan su miktarını karşılaştırmak</option><option value="energy">Gereksiz yanan ışık süresini karşılaştırmak</option><option value="access">Malzeme bulma süresini karşılaştırmak</option></select></label></div><button class="button navy" data-action="check-project">Planımı kontrol et ✓</button><p class="micro">Bu görev bir tasarım planı oluşturur. Gerçek saha etkisi ölçüldüğü anlamına gelmez.</p>`;
  return `<div class="exercise-heading"><h2>Proje günü hazırlığı</h2><span>Takım · Test · İyileştirme</span></div><div class="project-fields"><label>Takım nasıl çalışsın?<select id="final-team"><option value="">Çalışma biçimi seç</option><option value="roles">Tasarım, kurulum ve test rollerini paylaşalım.</option><option value="one">Her işi tek bir kişi yapsın.</option></select></label><label>Çalıştığını nasıl anlayalım?<select id="final-test"><option value="">Test seç</option><option value="looks">Güzel görünmesi yeterli.</option><option value="evidence">Farklı durumlarda deneyip sonuçları kaydedelim.</option></select></label><label>Beklenmeyen sonuçta ne yapalım?<select id="final-improve"><option value="">İyileştirme seç</option><option value="hide">Hatalı sonucu göstermeyelim.</option><option value="retry">Nedeni inceleyip bir değişiklikle tekrar deneyelim.</option></select></label></div><button class="button navy" data-action="check-final">Proje hazırlığını tamamla ✓</button><p class="micro">Tamamlama, demo proje planını kaydeder. Fiziksel proje öğretmen gözlemiyle ayrıca doğrulanır.</p>`;
 }
 function boardHTML(b){let html='';for(let y=0;y<b.size;y++)for(let x=0;x<b.size;x++){const start=x===b.start[0]&&y===b.start[1],goal=x===b.goal[0]&&y===b.goal[1],obstacle=b.obstacles.some(o=>o[0]===x&&o[1]===y);html+=`<div class="cell ${start?'robot-cell':''} ${goal?'goal-cell':''} ${obstacle?'obstacle-cell':''}" data-cell="${x},${y}" aria-label="${y+1}. satır ${x+1}. sütun${start?', robot başlangıcı':''}${goal?', hedef':''}${obstacle?', engel':''}"><span>${start?'◆':goal?'✦':obstacle?'■':''}</span>${start?'<small>BAŞLA</small>':goal?'<small>HEDEF</small>':''}</div>`}return html}
 function renderCommands(){if(!$('#command-list'))return;$('#command-count').textContent=commands.length+' / 24';$('#command-list').innerHTML=commands.length?commands.map((c,i)=>`<div class="command-token"><button data-remove="${i}" aria-label="${i+1}. ${D.directions[c]} komutunu çıkar">${D.arrows[c]}<small>${i+1}</small></button><div><button data-move-command="${i}" data-step="-1" ${i===0?'disabled':''} aria-label="${i+1}. komutu önceye taşı">‹</button><button data-move-command="${i}" data-step="1" ${i===commands.length-1?'disabled':''} aria-label="${i+1}. komutu sonraya taşı">›</button></div></div>`).join(''):'<span class="command-empty">Yön düğmelerine dokunarak ilk komutunu ekle.</span>'}
 function renderSequence(){$('#sequence-list').innerHTML=order.map((n,i)=>`<div class="sequence-item" draggable="true" data-drag="${i}"><b>${i+1}</b><span>${sequence[n]}</span><div><button data-sequence="${i}" data-step="-1" ${i===0?'disabled':''} aria-label="${sequence[n]} kartını yukarı taşı">↑</button><button data-sequence="${i}" data-step="1" ${i===order.length-1?'disabled':''} aria-label="${sequence[n]} kartını aşağı taşı">↓</button></div></div>`).join('');$('#sequence-list').querySelectorAll('[draggable]').forEach(el=>{el.addEventListener('dragstart',()=>dragIndex=Number(el.dataset.drag));el.addEventListener('dragover',e=>e.preventDefault());el.addEventListener('drop',e=>{e.preventDefault();const to=Number(el.dataset.drag);if(dragIndex===null)return;const val=order.splice(dragIndex,1)[0];order.splice(to,0,val);dragIndex=null;renderSequence()})})}
 function bindExercise(){renderCommands();if(theme().type==='sequence')renderSequence();if(theme().type==='verify')renderVerify();const ranges=[['water-threshold','water-out'],['distance-threshold','distance-out'],['left-motor','left-out'],['right-motor','right-out']];for(const [i,o]of ranges){const el=$('#'+i);if(el)el.addEventListener('input',()=>$('#'+o).textContent=el.value)}if($('#loop-count'))$('#loop-count').addEventListener('input',e=>loopCount=Math.max(1,Math.min(6,Number(e.target.value)||1)))}
 function feedback(text,kind='info'){const el=$('#task-feedback');if(el){el.textContent=text;el.className='task-feedback '+kind}}
 function complete(message){record('complete');feedback(message,'success');renderTransfer();toast('Dijital görev tamamlandı. Şimdi ekran dışında dene.');}
 function renderTransfer(){const el=$('#transfer');if(!el||!result().complete)return;const t=theme(),r=result();el.hidden=false;el.innerHTML=`<div><span class="eyebrow">ŞİMDİ EKRAN DIŞINDA</span><h2>Bunu gerçek dünyada dene.</h2><p>${t.physical}</p><p class="micro">Bir yetişkinle güvenli malzemeler kullan. Fiziksel tamamlanma öğretmen görünümünden ayrıca doğrulanır.</p></div><div class="transfer-actions"><button class="button mint" data-action="activity">Etkinlik kartını aç ↗</button><button class="quiet-button" data-action="reflect">${r.reflected?'✓ Öğrenme notum kaydedildi':'Ne öğrendiğimi kaydet'}</button><span>${r.physical?'✓ Öğretmen demo doğrulaması var':'Fiziksel etkinlik doğrulaması bekleniyor'}</span></div>`;}
 async function run(){if(running)return;const b=E.board(task,state.age),cmd=theme().type==='loop'?Array.from({length:loopCount},()=>['R','U']).flat():commands.slice();if(!cmd.length){feedback('Önce en az bir yön komutu ekle.');return}record('attempt');running=true;const version=++runVersion;const res=E.simulate(b,cmd);$('#game-board').innerHTML=boardHTML(b);feedback('Robot komutlarını deniyor…');const runButton=$('[data-action="run"]');runButton.disabled=true;
  for(let i=0;i<res.path.length;i++){if(version!==runVersion)return;document.querySelectorAll('.cell.robot-cell').forEach(c=>{c.classList.remove('robot-cell');c.querySelector('span').textContent=c.classList.contains('goal-cell')?'✦':''});const p=res.path[i],cell=$(`[data-cell="${p.join(',')}"]`);cell.classList.add('visited','robot-cell');cell.querySelector('span').textContent='◆';if(!matchMedia('(prefers-reduced-motion: reduce)').matches)await new Promise(resolve=>setTimeout(resolve,240));}
  if(version!==runVersion)return;running=false;runButton.disabled=false;if(res.success)complete('Hedefe ulaştın! Komutların doğru bir rota oluşturdu.');else if(res.error)feedback(`${res.index+1}. adımda durduk: ${res.error} Komutunu değiştirip yeniden dene.`,'error');else feedback('Komutlar bitti; hedefe henüz ulaşmadık. Kalan yolu düşün ve yeniden dene.','error');
 }
 function renderVerify(){const q=verifyQuestions[verifyIndex];$('#verify-progress').textContent=`${verifyIndex+1} / 3 soru`;$('#verify-area').innerHTML=`<p class="question-text">${q.q}</p><div class="answer-options">${q.options.map((o,i)=>`<button data-answer="${i}">${o}</button>`).join('')}</div><div id="answer-feedback" role="status"></div>`}
 function showActivity(){const t=theme();showDialog(t.title+' · Etkinlik kartı',`<span class="activity-badge">${t.id} · Örnek ekran dışı etkinlik</span><h3>Ne yapacağız?</h3><p>${t.physical}</p><h3>Nasıl başlayalım?</h3><ol class="activity-steps"><li>Bir yetişkinle görevi ve güvenli malzemeleri seç.</li><li>Önce ne olacağını tahmin et; ardından küçük bir deneme yap.</li><li>Sonucu anlat ve bir şeyi değiştirerek yeniden dene.</li></ol><h3>Birlikte gözlemleyelim</h3><p>${t.evidence}</p><h3>Malzeme ve güvenlik</h3><p>İlk denemede kâğıt kartlar, büyük nesneler ve düz bir çalışma alanı kullanılabilir. Kit, batarya, küçük parça, su ve hareketli robot içeren çalışmalar yetişkin denetimindedir. Demo donanım kurulumu yaptırmaz.</p><button class="button navy" data-action="download-card">Etkinlik kartını indir ↓</button><p class="footnote">İndirilen dosya kişisel veri içermeyen bir metin kartıdır.</p>`)}
 function showStory(){const t=theme();showDialog(t.story,`<span class="activity-badge">Örnek hikâye · Tamamlanmış animasyon değildir</span><h3>01 / Problemle karşılaş</h3><p>${t.intro}</p><h3>02 / Dur ve düşün</h3><p>${t.question}</p><h3>03 / Görevde dene</h3><p>${t.skill} becerilerini kullanarak çözümünü kur.</p><h3>04 / Hikâyeyi hayata taşı</h3><p>${t.physical}</p><button class="button mint" data-action="close">Göreve dön ▷</button>`,'DEMO İÇİN KURGULANMIŞ SENARYO')}
 function showPortfolio(){const done=D.themes.filter(t=>result(t.id).complete);showDialog('Öğrenme portfolyom',`<p>${D.profiles.find(p=>p.id===state.profile).name} · Yalnız bu cihazdaki demo kayıtları.</p>${done.length?`<div class="portfolio-list">${done.map(t=>`<article><strong>${t.id} · ${t.title}</strong><p>${result(t.id).attempts} deneme · ${result(t.id).hints} ipucu</p><span>${result(t.id).physical?'✓ Fiziksel etkinlik doğrulandı':'Fiziksel etkinlik bekliyor'}</span></article>`).join('')}</div>`:'<div class="empty-state"><h3>İlk öğrenme kaydına hazır.</h3><p>Bir dijital görevi tamamladığında burada görünecek.</p></div>'}<button class="button navy" data-action="export-progress">Demo gelişim özetini indir ↓</button>`)}
 function metricCards(s){return `<div class="metric-cards"><article><strong>${s.completed}</strong><span>Tamamlanan dijital görev</span></article><article><strong>${s.physical}</strong><span>Fiziksel doğrulama</span></article><article><strong>${s.attempts}</strong><span>Deneme kaydı</span></article><article><strong>${s.hints}</strong><span>İpucu kullanımı</span></article></div>`}
 function renderTeacher(){const s=E.stats(state,state.profile),p=D.profiles.find(x=>x.id===state.profile),completed=D.themes.filter(t=>result(t.id).complete);$('#workspace').innerHTML=`<div class="workspace-top"><div><span class="eyebrow">ÖĞRETMEN / SINIF AKIŞI</span><h1>Keşfi birlikte yönetin.</h1><p>${p.name} için görev atayın, dijital denemeleri izleyin ve fiziksel üretimi gözlemleyin.</p></div><button class="quiet-button" data-action="load-sample">Örnek sınıf verisi ekle</button></div>${metricCards(s)}<div class="dashboard-grid"><section class="dash-card"><h2>Görev atama</h2><form id="assignment-form"><label>Tema<select id="assign-task">${D.themes.map(t=>`<option value="${t.id}">${t.id} · ${t.title}</option>`).join('')}</select></label><label>Görevi kim denesin?<select id="assign-profile">${D.profiles.map(x=>`<option value="${x.id}" ${x.id===state.profile?'selected':''}>${x.name}</option>`).join('')}</select></label><label>Çalışma biçimi<select id="assign-mode"><option value="Birlikte keşif">Birlikte keşif</option><option value="Bağımsız deneme">Bağımsız deneme</option><option value="Takım etkinliği">Takım etkinliği</option></select></label><button class="button navy" type="submit">Demo görevi ata +</button></form><p class="micro">Atama bu tarayıcıdaki örnek hesaba eklenir; kimseye bildirim gönderilmez.</p></section><section class="dash-card"><h2>Atanan görevler</h2>${state.assignments.filter(a=>a.profile===state.profile).length?`<div class="assignment-list">${state.assignments.filter(a=>a.profile===state.profile).map(a=>`<article><strong>${esc(D.themes.find(t=>t.id===a.task)?.title)}</strong><p>${esc(a.mode)}</p><button class="quiet-button" data-open-task="${esc(a.task)}">Çocuk akışında aç ↗</button></article>`).join('')}</div>`:'<div class="empty-state"><span>＋</span><h3>Henüz görev atanmadı.</h3><p>Soldaki formdan bir tema seçerek ilk demo atamasını yapın.</p></div>'}</section></div><section class="dash-card physical-card"><h2>Fiziksel transfer ve gözlem</h2><p>Dijital görevin tamamlanması, fiziksel etkinliğin yapıldığını göstermez. Gözlemi ayrıca kaydedin.</p>${completed.length?`<form id="observation-form" class="observation-form"><label>Tamamlanan dijital görev<select id="observe-task">${completed.map(t=>`<option value="${t.id}">${t.id} · ${t.title}${result(t.id).physical?' · Doğrulandı':''}</option>`).join('')}</select></label><label>Gözlem sonucu<select id="observe-level"><option>Yetişkin desteğiyle uyguladı</option><option>Bağımsız uyguladı ve açıkladı</option><option>Yeni bir örneğe aktardı</option></select></label><label class="checkbox-label"><input id="confirm-physical" type="checkbox" required> Temsili senaryoda fiziksel etkinliğin gözlemlendiğini onaylıyorum.</label><button class="button navy" type="submit">Gözlemi kaydet ✓</button></form>`:'<div class="empty-state"><p>Doğrulama için önce çocuk alanında bir görev tamamlayın veya örnek sınıf verisini ekleyin.</p></div>'}${state.observations.filter(o=>o.profile===state.profile).map(o=>`<div class="observation-row"><strong>${esc(o.task)}</strong><span>${esc(o.level)}</span><span>Demo gözlemi</span></div>`).join('')}</section><section class="dash-card"><h2>Bugünün sınıf akışı</h2><ol class="class-flow"><li><strong>Keşfet</strong>Örnek hikâyeyi oku ve düşünme sorusunu sor.</li><li><strong>Dene</strong>Çocuğun komutlarını ve düzeltmelerini izle.</li><li><strong>Üret</strong>Güvenli materyalle fiziksel karşılığını uygula.</li><li><strong>Yansıt</strong>Çözümü anlattır; gözlemi ve transferi kaydet.</li></ol></section>`;$('#assignment-form').addEventListener('submit',e=>{e.preventDefault();const item={profile:$('#assign-profile').value,task:$('#assign-task').value,mode:$('#assign-mode').value};if(state.assignments.some(a=>a.profile===item.profile&&a.task===item.task)){toast('Bu görev bu kaşife zaten atanmış.');return}state.assignments.push(item);state.profile=item.profile;save();renderTeacher();toast('Demo görevi örnek kaşife atandı.');});$('#observation-form')?.addEventListener('submit',e=>{e.preventDefault();const id=$('#observe-task').value,level=$('#observe-level').value;E.record(state,state.profile,id,{type:'physical'});state.observations=state.observations.filter(o=>!(o.profile===state.profile&&o.task===id));state.observations.push({profile:state.profile,task:id,level});save();renderTeacher();toast('Öğretmen gözlemi veli ve portfolyo görünümüne yansıdı.');});}
 function renderParent(){const p=D.profiles.find(x=>x.id===state.profile),s=E.stats(state,state.profile),done=D.themes.filter(t=>result(t.id).complete),latest=done.at(-1);$('#workspace').innerHTML=`<div class="workspace-top"><div><span class="eyebrow">VELİ / GELİŞİM ÖZETİ</span><h1>Küçük adımları görün.</h1><p>${p.name} için bu tarayıcıdaki demo görevlerini ve öğretmen gözlemlerini inceleyin.</p></div><button class="quiet-button" data-action="export-progress">Özeti indir ↓</button></div>${metricCards(s)}<div class="dashboard-grid"><section class="dash-card"><h2>Çocuğum neler denedi?</h2>${done.length?`<div class="progress-list">${done.map(t=>`<article><span class="status-check">✓</span><div><strong>${t.title}</strong><p>${result(t.id).attempts} deneme · ${result(t.id).hints} ipucu</p><small>${result(t.id).physical?'Öğretmen demo doğrulaması: tamamlandı':'Fiziksel etkinlik: henüz doğrulanmadı'}</small></div></article>`).join('')}</div>`:'<div class="empty-state"><h3>Henüz tamamlanan görev yok.</h3><p>Çocuk alanında bir görev tamamlandığında gelişim özeti burada görünür.</p><button class="button navy" data-open-task="T01">İlk görevi birlikte dene ↗</button></div>'}</section><section class="dash-card parent-activity"><span class="eyebrow">EVDE BİRLİKTE</span><h2>${latest?latest.title:'Yön kartlarıyla küçük bir keşif'}</h2><p>${latest?latest.physical:'Evde güvenli, düz bir alanda başlangıç ve hedef seçin. Yön kartlarıyla küçük bir yol kurun.'}</p><h3>Sorabileceğiniz bir soru</h3><p>“Neyi değiştirdiğinde sonuç değişti? Bir kez daha denesek nasıl yapardın?”</p><button class="quiet-button" data-action="parent-card">Ev etkinliği kartını aç ↗</button></section></div><div class="parent-notes"><article><h3>İpucu almak öğrenmenin bir parçası.</h3><p>İpucu sayısı çocuğa verilen bir not değildir. Hangi desteğin işe yaradığını konuşmak için kullanılır.</p></article><article><h3>Dengeyi birlikte kurun.</h3><p>Görevden sonra hareket, oyun ve gerçek nesnelerle üretime geçin. Öğrenmeyi yalnız ekran süresine göre değerlendirmeyin.</p></article></div><section class="dash-card"><h2>Öğretmen gözlemleri</h2>${state.observations.filter(o=>o.profile===state.profile).map(o=>`<div class="observation-row"><strong>${esc(o.task)}</strong><span>${esc(o.level)}</span><span>Temsili gözlem</span></div>`).join('')||'<p class="micro">Bu örnek hesap için henüz öğretmen gözlemi yok.</p>'}</section>`}
 function renderInstitution(){const s=E.stats(state);$('#workspace').innerHTML=`<div class="workspace-top"><div><span class="eyebrow">KURUM / TOPLULAŞTIRILMIŞ GÖRÜNÜM</span><h1>Pilotun bütününü görün.</h1><p>Öğrenme kayıtları ve örnek saha senaryoları. Tüm kurumlar ve durumlar temsilidir; gerçek pilot verisi yoktur.</p></div><button class="quiet-button" data-action="load-sample">Örnek pilot verisi ekle</button></div>${metricCards(s)}<div class="institution-banner"><strong>3 örnek kaşif · 2 kurgusal okul modeli</strong><span>${state.scene==='sample'?'Örnek kayıtlar ve bu oturumdaki denemeler birlikte gösteriliyor.':'Göstergeler bu oturumdaki yerel demo kayıtlarından hesaplanır.'}</span></div><div class="dashboard-grid"><section class="dash-card"><h2>Okul modeli A · Robotik sınıf</h2><span class="activity-badge">KURGUSAL SENARYO</span><p class="school-story">Sabit kit ve görev cihazlarıyla haftalık öğrenme döngüsü. Öğretmen, dijital görevden sonra fiziksel üretimi doğrular.</p><ul class="check-list"><li>Sınıf içi komut ve parkur etkinliği</li><li>Asıl ve yedek öğretmen modeli</li><li>Gözlem, envanter ve bakım düzeni</li></ul></section><section class="dash-card"><h2>Okul modeli B · Gezici atölye</h2><span class="activity-badge">KURGUSAL SENARYO</span><p class="school-story">Sınırlı bağlantılı bir köy okuluna taşınabilir kit ve mentor desteği. Ziyaret öncesinde kartlarla hazırlık, sonrasında öğretmenle devam.</p><ul class="check-list"><li>Önceden indirilen içerik hedefi</li><li>Güvenli kurulum ve küçük gruplar</li><li>Ziyaret sonrası etkinlik ve takip</li></ul></section></div><section class="dash-card"><h2>Temalara göre öğrenme kanıtı</h2><p class="micro">Açık çocuk sıralaması yoktur. Bu tablo tema bazında toplulaştırılmış demo kayıtlarını gösterir.</p><div class="table-scroll"><table><thead><tr><th>Tema</th><th>Dijital tamamlama</th><th>Fiziksel doğrulama</th><th>Bekleyen transfer</th></tr></thead><tbody>${D.themes.map(t=>{const r=D.profiles.map(p=>result(t.id,p.id)),c=r.filter(x=>x.complete).length,f=r.filter(x=>x.physical).length;return `<tr><th>${t.title}</th><td>${c}</td><td>${f}</td><td>${Math.max(0,c-f)}</td></tr>`}).join('')}</tbody></table></div></section><section class="dash-card"><h2>Pilot hazır oluşunu inceleyin</h2><p>Okul seçimi, rol, donanım, güvenlik, eğitim ve prova tamamlandıktan sonra başlangıç kararı değerlendirilir.</p><div class="readiness-form">${['P0 · Okul seçimi ve taahhüt','P1 · Asıl / yedek roller','P2 · Mekân, kit ve çevrimdışı hazırlık','P3 · Çocuk güvenliği, veri ve izin','P4 · Öğretmen eğitimi ve prova'].map((t,i)=>`<label class="checkbox-label"><input type="checkbox" data-gate="${i}"> ${t}</label>`).join('')}</div><button class="button navy" data-action="check-gates">Hazır oluş senaryosunu değerlendir ✓</button><p id="gate-feedback" role="status" class="micro">Kutular bir kurum onayı oluşturmaz; karar mantığını canlandırır.</p></section>`;}
 function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob(['\ufeff'+text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function exportProgress(){const p=D.profiles.find(x=>x.id===state.profile);let text=`KOD KAŞİFLERİ — DEMO GELİŞİM ÖZETİ\n${p.name}\nBu belge yalnız yerel ve temsili demo kayıtlarını içerir. Gerçek öğrenci değerlendirmesi değildir.\n\n`;for(const t of D.themes){const r=result(t.id);text+=`${t.id} ${t.title}\nDijital görev: ${r.complete?'Tamamlandı':'Bekliyor'} | Deneme: ${r.attempts} | İpucu: ${r.hints} | Fiziksel doğrulama: ${r.physical?'Var':'Yok'}\n\n`}download('Kod_Kasifleri_Demo_Gelisim_Ozeti.txt',text)}
 function addSample(){const examples=[['k01','T01',3,1,true],['k01','T02',2,1,false],['k02','T08',2,2,true],['k02','T09',3,2,false],['k03','T01',2,2,false]];for(const[p,t,a,h,f]of examples){const key=p+':'+t;if(!state.results[key])state.results[key]={attempts:a,hints:h,complete:true,physical:f,reflected:true,sample:true};if(f&&!state.observations.some(o=>o.profile===p&&o.task===t))state.observations.push({profile:p,task:t,level:'Örnek kayıt: Yetişkin desteğiyle uyguladı'})}state.scene='sample';save();render();toast('Kurgusal örnek veriler eklendi. Kendi denemelerin korundu.');}
 function showScenarios(){showDialog('Bir senaryo seç',`<p>Aşağıdaki akışlar, aynı öğrenme kaydının farklı rollerde nasıl göründüğünü gösterir.</p><div class="scenario-options"><button data-scenario="first"><strong>01 · İlk keşfim</strong><span>Komut kur, çalıştır, ipucu al, hedefe ulaş.</span></button><button data-scenario="debug"><strong>02 · Hata bir ipucudur</strong><span>Yanlış rotayı dene ve komutları düzelt.</span></button><button data-scenario="class"><strong>03 · Öğretmenden aileye</strong><span>Örnek kayıt ekle, fiziksel görevi doğrula ve veli görünümünde izle.</span></button><button data-scenario="rural"><strong>04 · Köy okuluna erişim</strong><span>Gezici atölye ve pilot hazır oluş senaryosunu incele.</span></button></div><p class="footnote">Üçüncü senaryo kurgusal örnek kayıtlar ekler; mevcut denemelerini silmez.</p>`)}
 $('#profile-select').innerHTML=D.profiles.map(p=>`<option value="${p.id}">${p.name}</option>`).join('');$('#profile-select').addEventListener('change',e=>{state.profile=e.target.value;state.age=D.profiles.find(p=>p.id===state.profile).age;resetExercise();save();render()});$('#age-select').addEventListener('change',e=>{state.age=e.target.value;resetExercise();save();render();toast('Yaş katmanı değişti; yön parkuru ve sıralama görevi uyarlandı.')});
 $('#mission-toggle').addEventListener('click',()=>{const open=$('#mission-toggle').getAttribute('aria-expanded')==='true';$('#mission-toggle').setAttribute('aria-expanded',String(!open));$('#mission-list').classList.toggle('mobile-open',!open)});
 $('#portfolio-button').addEventListener('click',showPortfolio);$('#scenarios').addEventListener('click',showScenarios);$('#dialog-close').addEventListener('click',closeDialog);
 $('#about-demo').addEventListener('click',()=>showDialog('Demo nasıl çalışıyor?',`<p>Bu alan Kod Kaşifleri projesinin uygulama deneyimini göstermek için hazırlanmıştır. Kaşifler, okul modelleri, hikâyeler ve senaryolar temsilidir.</p><h3>Çalışan işlemler</h3><p>12 temaya ait örnek etkileşimler; ipucu, yerel ilerleme, görev atama, öğretmen doğrulaması, veli özeti ve toplu kurum görünümü.</p><h3>Canlandırılan bileşenler</h3><p>Yapay zekâ rehberi, robot hareketi ve sensörler hazır kurallar üzerinden çalışır. Gerçek öğrenci, robot, okul, bulut eşitleme veya yapay zekâ servisi bağlı değildir.</p><h3>Veri ve roller</h3><p>Demo şifresizdir. Rol düğmeleri güvenlik yetkisi değil, ürün akışını gösteren geçişlerdir. Gerçek hesap açılmaz; kişisel veri istenmez. Kayıtlar yalnız bu tarayıcıda tutulur ve alttaki sıfırlama düğmesiyle silinebilir.</p><p class="footnote">${storageOK?'Tarayıcı depolaması kullanılabilir.':'Bu tarayıcı depolamayı engelliyor; kayıtlar yalnız açık oturumda korunur.'}</p>`));
 $('#reset-demo').addEventListener('click',()=>showDialog('Demo kayıtları sıfırlansın mı?',`<p>Bu tarayıcıdaki örnek ilerleme, görev atamaları ve öğretmen gözlemleri silinir.</p><div class="dialog-actions"><button class="button navy" data-action="confirm-reset">Demo kayıtlarını sil</button><button class="quiet-button" data-action="close">Vazgeç</button></div>`));
 document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.role){setRole(b.dataset.role);return}
  if(b.dataset.task||b.dataset.openTask){setTask(b.dataset.task||b.dataset.openTask);$('#mission-list').classList.remove('mobile-open');$('#mission-toggle').setAttribute('aria-expanded','false');return}
  if(b.dataset.color){state.color=b.dataset.color;save();return}
  if(b.dataset.cmd){if(running)return;if(commands.length>=24){toast('Bu görevde en çok 24 komut kullanabilirsin.');return}commands.push(b.dataset.cmd);renderCommands();return}
  if(b.dataset.remove!==undefined){if(running)return;commands.splice(Number(b.dataset.remove),1);renderCommands();return}
  if(b.dataset.moveCommand!==undefined){if(running)return;const i=Number(b.dataset.moveCommand),j=i+Number(b.dataset.step);if(j<0||j>=commands.length)return;[commands[i],commands[j]]=[commands[j],commands[i]];renderCommands();return}
  if(b.dataset.sequence!==undefined){const i=Number(b.dataset.sequence),j=i+Number(b.dataset.step);if(j<0||j>=order.length)return;[order[i],order[j]]=[order[j],order[i]];renderSequence();return}
  if(b.dataset.label){labels[b.dataset.example]=b.dataset.label;classificationTested=false;$('#test-sample').hidden=true;document.querySelectorAll(`[data-example="${b.dataset.example}"]`).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));return}
  if(b.dataset.testLabel){if(!classificationTested)return;record('attempt');if(b.dataset.testLabel==='A')complete('Mavi daireyi doğru gruba aktardın. Bu görevde belirleyici özellik şekildi.');else feedback('Renk değişti, ama şekil hâlâ daire. Hangi gruba aitti?','error');return}
  if(b.dataset.answer!==undefined){record('attempt');const q=verifyQuestions[verifyIndex],good=Number(b.dataset.answer)===q.correct;if(!good){$('#answer-feedback').textContent='Bir kez daha düşün: kanıt ve güvenlik hangi seçenekte korunuyor?';feedback('İddiayı ve seçenekleri yeniden incele.','error');return}verifyCorrect++;document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);$('#answer-feedback').innerHTML=`<p>${q.feedback}</p>${verifyIndex<2?'<button class="button navy" data-action="next-question">Sonraki soru →</button>':'<strong>Üç durumu da güvenli biçimde değerlendirdin.</strong>'}`;if(verifyIndex===2)complete('İddia, kanıt ve mahremiyet konusunda üç doğru karar verdin.');return}
  if(b.dataset.scenario){const s=b.dataset.scenario;closeDialog();if(s==='first')setTask('T01');else if(s==='debug')setTask('T04');else if(s==='class'){addSample();setRole('teacher')}else setRole('institution');return}
  const action=b.dataset.action;if(!action)return;
  if(action==='close'){closeDialog();return}if(action==='story'){showStory();return}if(action==='activity'){showActivity();return}if(action==='run'){run();return}
  if(action==='clear'){runVersion++;running=false;commands=[];loopCount=1;renderChild();return}
  if(action==='hint'){const list=hints[theme().type]||hints.route;$('#hint-text').textContent=list[Math.min(hintLevel,list.length-1)];hintLevel++;record('hint');return}
  if(action==='check-sequence'){record('attempt');order.every((n,i)=>n===i)?complete('Adımları anlamlı bir sıraya koydun. Şimdi bunu kartlarla da dene.'):feedback('Bir adım henüz yerinde değil. Hazırlık, uygulamadan önce gelir.','error');return}
  if(action==='check-water'){record('attempt');const t=Number($('#water-threshold').value);$('#dry-status').textContent=25<t?'SULA':'DUR';$('#wet-status').textContent=70<t?'SULA':'DUR';E.watering(t)?complete('Kuralın kuru toprakta suluyor, nemli toprakta duruyor. İki farklı durumda da çalıştı.'):feedback('Kural iki örneği ayırmalı: kuru toprak sulansın, nemli toprakta sulama dursun.','error');return}
  if(action==='check-sensor'){record('attempt');const threshold=Number($('#distance-threshold').value),kind=$('#sensor-kind').value;$('#near-status').textContent=kind==='distance'?(10<threshold?'DUR':'İLERLE'):'Ölçüm uygun değil';$('#far-status').textContent=kind==='distance'?(80<threshold?'DUR':'İLERLE'):'Ölçüm uygun değil';kind==='distance'&&threshold>10&&threshold<=80?complete('Uygun sensörle yakın engelde durup açık yolda ilerleyen bir kural kurdun.'):feedback('Mesafeyi ölçen sensörü seç ve iki durumu ayıran bir eşik dene.','error');return}
  if(action==='check-event'){record('attempt');const good=$('#event-trigger').value==='button'&&$('#event-output').value==='light';$('#event-light').classList.toggle('lit',good);$('#event-message').textContent=good?'Düğmeye basıldı → ışık yandı.':'Seçtiğin düzenek bu olayda beklenen ışık tepkisini vermedi.';good?complete('Olayı ve tepkiyi eşleştirdin: düğmeye basılınca ışık yanıyor.'):feedback('Hikâyede düğmeye basılınca hangi tepki isteniyordu?','error');return}
  if(action==='check-motor'){record('attempt');const l=Number($('#left-motor').value),r=Number($('#right-motor').value);$('#motor-marker').style.transform=`translate(${l===r?0:(l>r?55:-55)}px,-45px) rotate(${(l-r)*12}deg)`;E.motor(l,r)?complete('Dengeli ve kontrollü hareket için iki motoru eşit, uygun hızda çalıştırdın.'):feedback(l!==r?'Hızlar farklı olduğu için robot yön değiştiriyor.':'Hızlar eşit ama bu yük için fazla yüksek. 1–3 aralığını dene.','error');return}
  if(action==='train'){if(Object.keys(labels).length<4){feedback('Önce dört örneğin de grubunu seç.');return}record('attempt');if(['A','B','A','B'].every((v,i)=>labels[i]===v)){classificationTested=true;$('#test-sample').hidden=false;feedback('Örnekler doğru. Şimdi yeni renkteki daireyi test et.');}else feedback('Bazı örnekler yanlış etiketlendi. Bu görevde renge değil şekle bak.','error');return}
  if(action==='next-question'){verifyIndex++;renderVerify();return}
  if(action==='check-project'){record('attempt');const p=$('#project-problem').value,s=$('#project-solution').value,m=$('#project-measure').value;p&&p===s&&s===m?complete('İhtiyaç, çözüm ve ölçüt tutarlı bir proje planında buluştu.'):feedback('İhtiyacın, çözümün ve ölçümün aynı probleme odaklandığından emin ol.','error');return}
  if(action==='check-final'){record('attempt');$('#final-team').value==='roles'&&$('#final-test').value==='evidence'&&$('#final-improve').value==='retry'?complete('Rol paylaşımı, test ve iyileştirme içeren proje planını tamamladın.'):feedback('Görev paylaşımı, kanıt üreten test ve yeniden deneme adımlarını birlikte düşün.','error');return}
  if(action==='reflect'){record('reflect');renderTransfer();toast('Öğrenme kapanışı portfolyona kaydedildi.');showDialog('Bugün ne öğrendim?',`<p>${theme().skill} becerilerini denedin. Bir yetişkine hangi adımı değiştirdiğini ve bunun sonucu nasıl etkilediğini anlat.</p><p class="footnote">Bu kayıt bir demo kapanış işaretidir; serbest metin veya ses kaydı alınmaz.</p>`);return}
  if(action==='download-card'){const t=theme();download(`Kod_Kasifleri_${t.id}_Etkinlik_Karti.txt`,`KOD KAŞİFLERİ — ÖRNEK ETKİNLİK KARTI\n${t.id}: ${t.title}\n\nBeceri: ${t.skill}\nEtkinlik: ${t.physical}\nDüşünme sorusu: ${t.question}\nGözlem: ${t.evidence}\n\nÖnce planla, güvenli malzemelerle dene, sonucu anlat ve bir değişiklikle tekrar dene.\nYetişkin eşliği gerekir. Gerçek robot kurulum talimatı değildir.\n`);return}
  if(action==='parent-card'){task=D.themes.filter(t=>result(t.id).complete).at(-1)?.id||'T01';showActivity();return}
  if(action==='export-progress'){exportProgress();return}if(action==='load-sample'){addSample();return}
  if(action==='check-gates'){const checks=[...document.querySelectorAll('[data-gate]')];$('#gate-feedback').textContent=checks.every(x=>x.checked)?'Örnek senaryoda P0–P4 hazır. P5 için yetkili kurulun kanıtları değerlendirmesi ve başlangıç kararı gerekir. Bu demo gerçek onay üretmez.':`${checks.filter(x=>!x.checked).length} hazırlık alanı eksik. Açık kritik koşullar tamamlanmadan başlangıç değerlendirilmez.`;return}
  if(action==='confirm-reset'){state=E.seed();try{localStorage.removeItem(KEY)}catch{}task='T01';role='child';resetExercise();closeDialog();save();render();toast('Bu tarayıcıdaki demo kayıtları sıfırlandı.');}
 });
 resetExercise();render();if(params.get('story'))showStory();if(!storageOK)toast('Kayıtlar yalnız açık oturumda korunuyor; tarayıcı depolaması kullanılamadı.');
 // Optional agent-facing, local-only interaction. No remote data access or authentication.
 const context=document.modelContext;
 if(context&&typeof context.registerTool==='function'){
  const lifecycle=new AbortController();
  try{Promise.resolve(context.registerTool({
   name:'navigate_kod_kasifleri_demo',title:'Kod Kaşifleri demo görünümünü aç',
   description:'Open a local demo role and theme. Does not complete a task or create records.',
   inputSchema:{type:'object',properties:{role:{type:'string',enum:Object.keys(D.roles)},theme:{type:'string',enum:D.themes.map(t=>t.id)}},additionalProperties:false},
   annotations:{readOnlyHint:false,untrustedContentHint:false},
   execute:async input=>{
    if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['role','theme'].includes(k))||(Object.hasOwn(input,'role')&&!Object.keys(D.roles).includes(input.role))||(Object.hasOwn(input,'theme')&&!D.themes.some(t=>t.id===input.theme)))throw new Error('Geçersiz rol veya tema.');
    if(input.theme){task=input.theme;resetExercise()}if(input.role)role=input.role;render();
    return{role,theme:task,scope:'local-demo'};
   }
  },{signal:lifecycle.signal})).catch(()=>{});}catch{}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 }
})();
